package org.fm1.wrapper;
import android.graphics.*;
import android.media.*;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Mobile sample builder: waveform chops, named drum lanes and instrument roots. */
final class SampleEditor {
 final AndroidPanels p;final int slot,mode;final ArrayList<SampleCodec.Zone> zones;final short[] original;final TreeSet<Integer> cuts=new TreeSet<>();
 AudioTrack audition;int auditionLength;
 SampleEditor(AndroidPanels p,int slot,int mode,ArrayList<SampleCodec.Zone> zones){this.p=p;this.slot=slot;this.mode=mode;this.zones=zones;original=zones.get(0).pcm;cuts.add(0);cuts.add(original.length);}
 void stop(){if(audition!=null){audition.stop();audition.release();audition=null;}}
 void play(short[] pcm){stop();audition=new AudioTrack.Builder().setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).build()).setAudioFormat(new AudioFormat.Builder().setSampleRate(SampleCodec.RATE).setEncoding(AudioFormat.ENCODING_PCM_16BIT).setChannelMask(AudioFormat.CHANNEL_OUT_MONO).build()).setTransferMode(AudioTrack.MODE_STATIC).setBufferSizeInBytes(pcm.length*2).build();audition.write(pcm,0,pcm.length);auditionLength=pcm.length;audition.play();}
 void split(){zones.clear();Integer[] a=cuts.toArray(new Integer[0]);for(int i=0;i<a.length-1;i++){SampleCodec.Zone z=new SampleCodec.Zone(Arrays.copyOfRange(original,a[i],a[i+1]),"CHOP "+(i+1));z.root=53+i;zones.add(z);}}
 void show(){p.ui.closeSheets();LinearLayout b=p.body("sampleBuilder");if(mode==1){b.addView(new Wave(),p.ui.lpFill(120));p.line(b,"Tap waveform to add/remove a cut. Up to 16 chops.");p.add(b,"PLAY RECORDING",()->play(original));p.add(b,"TAP CUT DURING PLAY",()->{if(audition!=null&&cuts.size()<17){int t=audition.getPlaybackHeadPosition();if(t>0&&t<original.length){cuts.add(t);split();show();}}});p.add(b,"EQUAL PARTS",()->p.ui.numberEditor("CHOPS",8,1,16,n->{cuts.clear();for(int i=0;i<=n;i++)cuts.add((int)((long)original.length*i/n));split();show();}));p.add(b,"FIND HITS",()->{cuts.clear();cuts.add(0);cuts.add(original.length);int last=0;double previous=0;for(int i=0;i+256<original.length&&cuts.size()<17;i+=256){double e=0;for(int j=0;j<256;j++)e+=Math.abs(original[i+j]);e/=256;if(e>2000&&e>previous*2&&i-last>SampleCodec.RATE/12){cuts.add(i);last=i;}previous=e;}split();show();});}
  int total=0;for(SampleCodec.Zone z:zones)if(z.keep)total+=z.pcm.length;p.line(b,String.format(java.util.Locale.ROOT,"%.2f / %.2f SECONDS",total/(float)SampleCodec.RATE,SampleCodec.MAX*2f/SampleCodec.RATE));
  for(int i=0;i<zones.size();i++){final int ix=i;SampleCodec.Zone z=zones.get(i);p.add(b,(z.keep?"✓ ":"— ")+z.name+" · "+z.pcm.length*1000/SampleCodec.RATE+" MS",()->edit(ix));}
  p.add(b,"FIT TO SLOT",()->{SampleCodec.fit(zones);show();});p.add(b,"SEND TO USR"+(slot+1),()->{try{byte[] data=SampleCodec.slot(zones,"USR"+(slot+1),mode==2);stop();Native.sample(slot,data);Toast.makeText(p.ui.getContext(),"Sample queued. Use this slot on a track after loading.",Toast.LENGTH_LONG).show();}catch(IllegalArgumentException e){Toast.makeText(p.ui.getContext(),e.getMessage(),Toast.LENGTH_LONG).show();}});
  p.add(b,"USE SLOT ON SELECTED TRACK",()->p.action(49,slot));android.app.Dialog d=p.sheet(mode==1?"CHOP RECORDING":mode==2?"BUILD DRUM KIT":"BUILD INSTRUMENT",b);p.ui.sheetCleanup(d,()->stop());
 }
 void edit(int i){SampleCodec.Zone z=zones.get(i);LinearLayout b=p.body("sampleZone");p.add(b,"PLAY",()->play(z.pcm));p.add(b,z.keep?"LEAVE OUT":"KEEP",()->{z.keep=!z.keep;show();});if(mode!=2)p.add(b,"ROOT NOTE: "+z.root,()->p.ui.numberEditor("MIDI ROOT",z.root,0,127,n->{z.root=n;show();}));else p.add(b,"ASSIGN DRUM LANE",()->{String[] lanes=p.strings(p.state().optJSONArray("lanes"));p.choose("DRUM LANE",lanes,i,n->{int[] notes=p.ui.definition.drumNotes;z.root=z.lo=z.hi=notes[n];z.name=lanes[n];show();});});p.add(b,"TRIM LENGTH",()->p.ui.numberEditor("LENGTH / MS",z.pcm.length*1000/SampleCodec.RATE,1,Math.max(1,z.pcm.length*1000/SampleCodec.RATE),n->{z.pcm=Arrays.copyOf(z.pcm,Math.min(z.pcm.length,n*SampleCodec.RATE/1000));show();}));p.add(b,"GAIN / %",()->p.ui.numberEditor("GAIN",100,0,200,n->{for(int j=0;j<z.pcm.length;j++)z.pcm[j]=(short)Math.max(-32768,Math.min(32767,z.pcm[j]*n/100));show();}));p.ui.sheetCleanup(p.sheet(z.name,b),()->stop());}
 final class Wave extends View {final Paint pen=new Paint();Wave(){super(p.ui.getContext());setContentDescription("Waveform. Tap to add or remove chop markers.");}protected void onDraw(Canvas c){pen.setColor(StudioView.GREEN);int w=getWidth(),h=getHeight();for(int x=0;x<w;x++){int start=(int)((long)x*original.length/w),end=(int)((long)(x+1)*original.length/w),peak=0;for(int i=start;i<end;i++)peak=Math.max(peak,Math.abs((int)original[i]));c.drawLine(x,h/2f-peak*h/65536f,x,h/2f+peak*h/65536f,pen);}pen.setColor(StudioView.TEXT);for(int i:cuts){float x=i*(float)w/original.length;c.drawLine(x,0,x,h,pen);}}public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_UP){int pos=Math.max(0,Math.min(original.length,(int)(e.getX()*original.length/getWidth())));Integer near=cuts.floor(pos);if(near!=null&&near>0&&Math.abs(near-pos)<original.length/40)cuts.remove(near);else if(pos>0&&pos<original.length&&cuts.size()<17)cuts.add(pos);split();invalidate();show();performClick();}return true;}public boolean performClick(){super.performClick();return true;}}
}
